#!/usr/bin/env python3
"""Minimal pcapng reader + Ethernet/IPv4/IPv6/TCP/UDP decoder.

There is no tshark, tcpdump, scapy or dpkt in this workspace, so this parses the
file directly. It is deliberately dependency-free and read-only.

Usage:
    python3 tools/pcapng_read.py FILE.pcapng            # summary report
    python3 tools/pcapng_read.py FILE.pcapng --csv      # one line per packet
    python3 tools/pcapng_read.py FILE.pcapng --json OUT # machine-readable
"""
import json
import struct
import sys
from collections import OrderedDict, defaultdict

# ---------------------------------------------------------------- pcapng

BT_SHB = 0x0A0D0D0A
BT_IDB = 0x00000001
BT_PB = 0x00000002
BT_SPB = 0x00000003
BT_EPB = 0x00000006

LINKTYPE_ETHERNET = 1
LINKTYPE_RAW = 101
LINKTYPE_LINUX_SLL = 113
LINKTYPE_LINUX_SLL2 = 276
LINKTYPE_NULL = 0


class Interface:
    def __init__(self, iid):
        self.id = iid
        self.linktype = 0
        self.snaplen = 0
        self.tsresol = 6          # default: microseconds
        self.tsresol_units = 1e-6  # seconds per tick
        self.name = ''
        self.description = ''
        self.if_tsoffset = 0

    def __repr__(self):
        return (f'<if{self.id} link={self.linktype} snaplen={self.snaplen} '
                f'ts={self.name or self.description!r}>')


def _parse_options(buf, endian):
    """Parse pcapng option list. Returns dict code -> [values]."""
    opts = defaultdict(list)
    off = 0
    while off + 4 <= len(buf):
        code, length = struct.unpack_from(endian + 'HH', buf, off)
        off += 4
        if code == 0 and length == 0:
            break
        val = buf[off:off + length]
        opts[code].append(val)
        off += (length + 3) & ~3
    return opts


def read_pcapng(path):
    """Yield (ts_seconds, iface, linktype, raw_bytes) for every packet."""
    with open(path, 'rb') as fh:
        data = fh.read()

    interfaces = []
    off = 0
    endian = '<'
    n = len(data)
    while off + 12 <= n:
        btype, blen = struct.unpack_from(endian + 'II', data, off)
        if btype == BT_SHB:
            # byte-order magic at offset 8 tells us the true endianness
            bom = data[off + 8:off + 12]
            if bom == b'\x1a\x2b\x3c\x4d':
                endian = '<'
            elif bom == b'\x4d\x3c\x2b\x1a':
                endian = '>'
            else:
                raise ValueError(f'bad byte-order magic at {off}: {bom!r}')
            _, blen = struct.unpack_from(endian + 'II', data, off)
        if blen < 12 or off + blen > n:
            # tolerate truncation at the tail
            break
        body = data[off + 8:off + blen - 4]

        if btype == BT_IDB:
            iface = Interface(len(interfaces))
            iface.linktype, iface.snaplen = struct.unpack_from(endian + 'HH', body, 0)
            opts = _parse_options(body[8:], endian)
            if 9 in opts:                       # if_tsresol
                raw = opts[9][0][0]
                if raw & 0x80:
                    iface.tsresol_units = 2.0 ** -(raw & 0x7f)
                else:
                    iface.tsresol_units = 10.0 ** -raw
            if 14 in opts:                      # if_tsoffset
                iface.if_tsoffset = struct.unpack(endian + 'I', opts[14][0])[0]
            for code, attr in ((2, 'name'), (3, 'description')):
                if code in opts:
                    setattr(iface, attr, opts[code][0].decode('utf-8', 'replace'))
            interfaces.append(iface)
        elif btype == BT_EPB:
            iid, tsh, tsl, caplen, origlen = struct.unpack_from(endian + 'IIIII', body, 0)
            iface = interfaces[iid] if iid < len(interfaces) else Interface(iid)
            ts = ((tsh << 32) | tsl) * iface.tsresol_units + iface.if_tsoffset
            pkt = body[20:20 + caplen]
            yield ts, iface, iface.linktype, pkt
        elif btype == BT_SPB:
            if not interfaces:
                off += blen
                continue
            iface = interfaces[0]
            origlen = struct.unpack_from(endian + 'I', body, 0)[0]
            pkt = body[4:4 + min(origlen, iface.snaplen or len(body) - 4)]
            yield 0.0, iface, iface.linktype, pkt
        elif btype == BT_PB:
            iid, tsh, tsl, caplen, origlen = struct.unpack_from(endian + 'IIIII', body, 0)
            iface = interfaces[iid] if iid < len(interfaces) else Interface(iid)
            ts = ((tsh << 32) | tsl) * iface.tsresol_units + iface.if_tsoffset
            yield ts, iface, iface.linktype, body[20:20 + caplen]
        off += blen
    return interfaces


# ---------------------------------------------------------------- decode

ETHERTYPE_IP4 = 0x0800
ETHERTYPE_IP6 = 0x86DD
ETHERTYPE_ARP = 0x0806
ETHERTYPE_VLAN = 0x8100
ETHERTYPE_QINQ = 0x88A8


def _mac(b):
    return ':'.join('%02x' % x for x in b)


def _ip4(b):
    return '.'.join(str(x) for x in b)


def _ip6(b):
    return ':'.join('%x' % struct.unpack_from('!H', b, i)[0] for i in range(0, 16, 2))


def decode_ethernet(raw):
    """Return dict with l3 info, or None if not IP."""
    if len(raw) < 14:
        return None
    dst, src, etype = _mac(raw[0:6]), _mac(raw[6:12]), struct.unpack_from('!H', raw, 12)[0]
    off = 14
    while etype in (ETHERTYPE_VLAN, ETHERTYPE_QINQ) and len(raw) >= off + 4:
        etype = struct.unpack_from('!H', raw, off + 2)[0]
        off += 4
    if etype == ETHERTYPE_IP4:
        ip = decode_ip4(raw, off)
    elif etype == ETHERTYPE_IP6:
        ip = decode_ip6(raw, off)
    elif etype == ETHERTYPE_ARP:
        ip = {'l3': 'arp', 'src': src, 'dst': dst, 'raw': raw[off:]}
    else:
        ip = {'l3': 'other', 'ethertype': hex(etype), 'src': src, 'dst': dst}
    if ip is None:
        return None
    ip['eth_src'], ip['eth_dst'], ip['eth_type'] = src, dst, etype
    return ip


def decode_ip4(raw, off):
    if len(raw) < off + 20:
        return None
    vihl, tos, totlen, ident, flags_frag, ttl, proto, csum = \
        struct.unpack_from('!BBHHHBBH', raw, off)
    ihl = (vihl & 0x0f) * 4
    src = _ip4(raw[off + 12:off + 16])
    dst = _ip4(raw[off + 16:off + 20])
    frag_off = flags_frag & 0x1fff
    mf = bool(flags_frag & 0x2000)
    df = bool(flags_frag & 0x4000)
    out = {'l3': 'ip4', 'src': src, 'dst': dst, 'proto': proto, 'ttl': ttl,
           'totlen': totlen, 'ident': ident, 'df': df, 'mf': mf,
           'frag_off': frag_off, 'hl': ihl}
    payload = raw[off + ihl:]
    if proto == 6 and frag_off == 0:
        out['l4'] = decode_tcp(payload, src, dst)
    elif proto == 17 and frag_off == 0:
        out['l4'] = decode_udp(payload, src, dst)
    return out


def decode_ip6(raw, off):
    if len(raw) < off + 40:
        return None
    first = struct.unpack_from('!I', raw, off)[0]
    vtc = first >> 28
    if vtc != 6:
        return None
    plen, nxt, hop = struct.unpack_from('!HBB', raw, off + 4)
    src = _ip6(raw[off + 8:off + 24])
    dst = _ip6(raw[off + 24:off + 40])
    out = {'l3': 'ip6', 'src': src, 'dst': dst, 'proto': nxt, 'ttl': hop,
           'totlen': plen + 40}
    payload = raw[off + 40:]
    if nxt == 6:
        out['l4'] = decode_tcp(payload, src, dst)
    elif nxt == 17:
        out['l4'] = decode_udp(payload, src, dst)
    return out


def decode_udp(payload, src, dst):
    if len(payload) < 8:
        return None
    sport, dport, ulen, csum = struct.unpack_from('!HHHH', payload, 0)
    return {'l4': 'udp', 'sport': sport, 'dport': dport, 'len': ulen}


TCP_FLAGS = [('FIN', 0x01), ('SYN', 0x02), ('RST', 0x04), ('PSH', 0x08),
             ('ACK', 0x10), ('URG', 0x20), ('ECE', 0x40), ('CWR', 0x80)]


def decode_tcp(payload, src, dst):
    if len(payload) < 20:
        return None
    sport, dport, seq, ack, off_flags, win, csum, urg = \
        struct.unpack_from('!HHIIHHHH', payload, 0)
    doff = (off_flags >> 12) * 4
    flags = off_flags & 0x01ff
    out = {'l4': 'tcp', 'sport': sport, 'dport': dport, 'seq': seq,
           'ack': ack, 'flags': flags, 'win': win, 'urg': urg,
           'flags_str': ','.join(n for n, m in TCP_FLAGS if flags & m) or 'none',
           'hdr_len': doff, 'options': {}}
    if doff > 20:
        opts = payload[20:doff]
        o = 0
        while o < len(opts):
            kind = opts[o]
            if kind == 0:
                out['options']['EOL'] = True
                break
            if kind == 1:
                o += 1
                continue
            if o + 1 >= len(opts):
                break
            olen = opts[o + 1]
            body = opts[o + 2:o + olen]
            if kind == 2:
                out['options']['MSS'] = struct.unpack('!H', body[:2])[0]
            elif kind == 3:
                out['options']['WS'] = body[0] if body else 0
            elif kind == 4:
                out['options']['SACKOK'] = True
            elif kind == 5:
                out['options']['SACK'] = [struct.unpack_from('!II', body, i)
                                          for i in range(0, len(body) - 7, 8)]
            elif kind == 8:
                out['options']['TS'] = struct.unpack('!II', body[:8])
            o += max(olen, 2)
    return out


def packets(path):
    """Yield (ts, iface, eth_dict) for decoded Ethernet frames."""
    for ts, iface, linktype, raw in read_pcapng(path):
        if linktype == LINKTYPE_ETHERNET:
            d = decode_ethernet(raw)
        elif linktype in (LINKTYPE_RAW,):
            d = decode_ip4(raw, 0) if (raw and raw[0] >> 4) == 4 else decode_ip6(raw, 0)
        elif linktype == LINKTYPE_LINUX_SLL:
            etype = struct.unpack_from('!H', raw, 14)[0]
            d = decode_ethernet(b'\x00' * 12 + struct.pack('!H', etype) + raw[16:])
        else:
            d = None
        yield ts, iface, raw, d


# ---------------------------------------------------------------- analysis

def flow_key(d, reverse=False):
    l4 = d.get('l4') or {}
    a = (d['src'], l4.get('sport'))
    b = (d['dst'], l4.get('dport'))
    if reverse:
        a, b = b, a
    return (a, b, l4.get('l4', d.get('l3')))


def main(argv):
    if len(argv) < 2:
        print(__doc__)
        return 2
    path = argv[1]
    as_csv = '--csv' in argv
    json_out = None
    if '--json' in argv:
        json_out = argv[argv.index('--json') + 1]

    # first pass: interfaces + packet count + tcp records
    ifaces = []
    seen_iface = set()
    recs = []
    iface_stats = defaultdict(int)
    t0 = None
    t1 = None
    for ts, iface, raw, d in packets(path):
        if iface.id not in seen_iface:
            seen_iface.add(iface.id)
            ifaces.append(iface)
        iface_stats[iface.id] += 1
        if t0 is None or ts < t0:
            t0 = ts
        if t1 is None or ts > t1:
            t1 = ts
        recs.append((ts, iface, raw, d))

    print(f'== {path}')
    print(f'packets: {len(recs)}   duration: {t1 - t0:.3f} s' if t0 else 'no packets')
    for i in ifaces:
        print(f'  {i!r}  packets={iface_stats[i.id]}')

    if as_csv:
        for ts, iface, raw, d in recs:
            if not d:
                print(f'{ts - t0:.6f},{iface.id},len={len(raw)},undecoded')
                continue
            l4 = d.get('l4') or {}
            print(','.join(str(x) for x in [
                f'{ts - t0:.6f}', iface.id, d.get('l3'),
                d.get('src'), l4.get('sport'), d.get('dst'), l4.get('dport'),
                l4.get('flags_str', ''), l4.get('seq', ''), l4.get('ack', ''),
                l4.get('win', ''), len(raw)]))
        return 0

    # ---- summarize flows
    flows = OrderedDict()
    for ts, iface, raw, d in recs:
        if not d or 'l4' not in d:
            continue
        l4 = d['l4']
        if l4['l4'] not in ('tcp', 'udp'):
            continue
        k = flow_key(d)
        f = flows.setdefault(k, {
            'key': k, 'pkts': 0, 'bytes': 0, 'first': ts, 'last': ts,
            'l3': d['l3'], 'eth': (d.get('eth_src'), d.get('eth_dst')),
            'syn': 0, 'synack': 0, 'fin': 0, 'rst': 0, 'psh': 0,
            'from_a': 0, 'from_b': 0, 'payload_from_a': 0, 'payload_from_b': 0,
        })
        f['pkts'] += 1
        f['bytes'] += len(raw)
        f['last'] = ts
        fl = l4.get('flags', 0) if l4['l4'] == 'tcp' else 0
        pay = len(raw) - 14 - (d.get('hl') or 20) - l4.get('hdr_len', 8)
        if l4['l4'] == 'tcp':
            if fl & 0x02:
                f['syn'] += 1
                if fl & 0x10:
                    f['synack'] += 1
            if fl & 0x01:
                f['fin'] += 1
            if fl & 0x04:
                f['rst'] += 1
            if fl & 0x08:
                f['psh'] += 1
        if (d['src'], l4['sport']) == k[0]:
            f['from_a'] += 1
            f['payload_from_a'] += max(pay, 0)
        else:
            f['from_b'] += 1
            f['payload_from_b'] += max(pay, 0)

    print('\n== flows (a = first direction seen)')
    for k, f in flows.items():
        a, b, proto = k
        dur = f['last'] - f['first']
        print(f'  {a[0]}:{a[1]} <-> {b[0]}:{b[1]} [{proto}] '
              f'pkts={f["pkts"]} dur={dur:.3f}s syn={f["syn"]} '
              f'synack={f["synack"]} fin={f["fin"]} rst={f["rst"]} '
              f'psh={f["psh"]} '
              f'payload {f["payload_from_a"]}B/{f["payload_from_b"]}B '
              f'eth {f["eth"][0]}->{f["eth"][1]}')

    if json_out:
        with open(json_out, 'w') as fh:
            json.dump([{**{kk: vv for kk, vv in v.items() if kk != 'key'},
                        'a': list(v['key'][0]), 'b': list(v['key'][1]),
                        'proto': v['key'][2],
                        'start': v['first'] - t0, 'end': v['last'] - t0}
                       for v in flows.values()], fh, indent=1)
        print(f'\nwrote {json_out}')
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

