#!/usr/bin/env python3
"""De-interleave two console lines that a shared console wrote character by
character, using the format strings the code actually prints.

    A: "  us/frame:" then " <stage> <mean>/<max>" for each stage,
       then " sum <t> vs period <p>"
    B: "CAMENC WS: <live> client(s), pending <p>, sent <s>, skipped <k>,
        served <v>, dropped <d>"

Usage: python3 tools/deinterleave_log.py "<the garbled line>"
"""
import sys

STAGES = ["camera", "copy", "encode", "drain", "mux", "file", "clients",
          "serve"]


def build_a():
    toks = [("lit", "  us/frame:")]
    for s in STAGES:
        toks += [("lit", " " + s + " "), ("num",), ("lit", "/"), ("num",)]
    toks += [("lit", " sum "), ("num",), ("lit", " vs period "), ("num",),
             ("lit", "\n")]
    return toks


def build_b():
    return [("lit", "CAMENC WS: "), ("num",), ("lit", " client(s), pending "),
            ("num",), ("lit", ", sent "), ("num",), ("lit", ", skipped "),
            ("num",), ("lit", ", served "), ("num",), ("lit", ", dropped "),
            ("num",), ("lit", "\n")]


def start(toks):
    return (0, 0, 0)          # token, offset in literal, digits taken


def step(toks, st, ch):
    """Advance one template by one character; return the new state or None."""
    ti, off, ndig = st
    if ti >= len(toks):
        return None
    kind = toks[ti][0]
    if kind == "lit":
        lit = toks[ti][1]
        if off < len(lit) and lit[off] == ch:
            off += 1
            if off == len(lit):
                return (ti + 1, 0, 0)
            return (ti, off, 0)
        return None
    # number: consume digits, and allow leaving once at least one was taken
    if ch.isdigit():
        return (ti, 0, ndig + 1)
    if ndig > 0:
        nxt = (ti + 1, 0, 0)
        return step(toks, nxt, ch)
    return None


def done(toks, st):
    ti, off, ndig = st
    if ti >= len(toks):
        return True
    return False


def solve(m, toksA, toksB):
    seen = set()
    out = []

    def rec(i, sa, sb, accA, accB):
        if i == len(m):
            if done(toksA, sa) and done(toksB, sb):
                out.append(("".join(accA), "".join(accB)))
                return True
            return False
        key = (i, sa, sb)
        if key in seen:
            return False
        seen.add(key)
        ch = m[i]
        # try feeding ch to A first, then B; also allow ch to be dropped when
        # it fits neither (a terminal can lose a character mid-race)
        for which in (0, 1, 2):
            if which == 0:
                ns = step(toksA, sa, ch)
                if ns and rec(i + 1, ns, sb, accA + [ch], accB):
                    return True
            elif which == 1:
                ns = step(toksB, sb, ch)
                if ns and rec(i + 1, sa, ns, accA, accB + [ch]):
                    return True
            else:
                if rec(i + 1, sa, sb, accA, accB):
                    return True
        return False

    if rec(0, start(toksA), start(toksB), [], []):
        return out[0]
    return None


if __name__ == '__main__':
    line = " ".join(sys.argv[1:]) if len(sys.argv) > 1 else sys.stdin.read()
    line = line.rstrip("\n")
    r = solve(line, build_a(), build_b())
    if r is None:
        print("could not split; the paste may be missing characters")
    else:
        a, b = r
        print("A (us/frame) :", a.rstrip())
        print("B (ws report):", b.rstrip())

