void camenc_ws_ready(FAR struct camenc_ws_s *ws, FAR struct pollfd *fds, int n)
{
  int i;

  if (ws == NULL || ws->listen_fd < 0)
    {
      return;
    }

  for (i = 0; i < n; i++)
    {
      FAR struct camenc_ws_client_s *c;
      uint64_t mark;

      if (fds[i].revents == 0)
        {
          continue;
        }

      /* Each of the three calls below is timed on its own, because the caller
       * times all of them together and "the sockets took 37 ms" is true of
       * every one of them -- see camenc_ws_phases_s.  The times are taken
       * around the calls here rather than inside them so that the entry and
       * exit of each is in one place; the counts are taken inside, where each
       * one is known.
       */

      if (fds[i].fd == ws->listen_fd)
        {
          mark = ws_now_us();
          ws_accept(ws);
          ws_phase(&ws->phases.accept_us, &ws->phases.accept_max,
                   ws_now_us() - mark);
          continue;
        }

      c = ws_client_for(ws, fds[i].fd);
      if (c == NULL)
        {
          continue;
        }

      /* A hangup is read for rather than acted on directly: the read is what
       * finds the end of the stream, and it is also where a client that has
       * gone away is let go of -- see ws_read_client().
       */

      if ((fds[i].revents & (POLLIN | POLLHUP | POLLERR)) != 0)
        {
          mark = ws_now_us();
          ws->phases.reads++;
          ws_read_client(ws, c);
          ws_phase(&ws->phases.read_us, &ws->phases.read_max,
                   ws_now_us() - mark);

          if (c->fd < 0)
            {
              continue;
            }
        }

      if ((fds[i].revents & POLLOUT) != 0)
        {
          mark = ws_now_us();
          ws->phases.flushes++;
          ws_flush(ws, c);
          ws_phase(&ws->phases.flush_us, &ws->phases.flush_max,
                   ws_now_us() - mark);
        }
    }
}

void camenc_ws_take_phases(FAR struct camenc_ws_s *ws,
                           FAR struct camenc_ws_phases_s *phases)
{
  if (ws == NULL || phases == NULL)
    {
      return;
    }

  *phases = ws->phases;
  memset(&ws->phases, 0, sizeof(ws->phases));
}

