{
  switch (-status)
    {
      case EACCES:
      case EPERM:
        return "EPERM";
      case ESTALE:
      case EEXIST:
        return "ECONFLICT";
      case EALREADY:
        return "EALREADY";
      case ECANCELED:
        return "ECANCELED";
      case ENOENT:
        return "ENOTFOUND";
      case ENODEV:
      case ENOTSUP:
        return "EUNAVAILABLE";
      case ENODATA:
        return "ENOTCONFIGURED";
      case E2BIG:
      case ENOSPC:
        return "EQUOTA";
      case ENOMEM:
        return "ENOMEM";
      case ETIMEDOUT:
        return "ETIMEDOUT";
      case EBUSY:
      case EAGAIN:
        return "EBUSY";
      case EIO:
      case EBADMSG:
        return "EIO";

      /* The refusals of update.apply.  Each asks something different of
       * the owner, so none of them may fold into EINVAL: acknowledge the
       * advanced targets, pick another slot, agree to write under a mounted
       * filesystem, or give up on a target that is never written.
