#define NYABULA_WS_IO_MS      2000
#define NYABULA_WS_HEADER_MAX 4096

/* Frames up to this size are assembled on the stack; client threads run on
 * 32 KiB, and most replies fit.
 */

#define NYABULA_WS_COALESCE_MAX 1024
